   482  static unsigned
   483  xmlDictHashQName(unsigned seed, const xmlChar *prefix, const xmlChar *name,
   484                   size_t *pplen, size_t *plen) {
   485      unsigned h1, h2;
   486      size_t i;
   487
   488      HASH_INIT(h1, h2, seed);
   489
   490      for (i = 0; prefix[i] != 0; i++) {
   491          HASH_UPDATE(h1, h2, prefix[i]);
   492      }
   493      *pplen = i;
   494
