   496
   497      for (i = 0; name[i] != 0; i++) {
   498          HASH_UPDATE(h1, h2, name[i]);
   499      }
   500      *plen = i;
   501
   502      HASH_FINISH(h1, h2);
   503
   504      /*
   505       * Always set the upper bit of hash values since 0 means an unoccupied
   506       * bucket.
   507       */
   508      return(h2 | MAX_HASH_SIZE);
