   520  unsigned
   521  xmlDictCombineHash(unsigned v1, unsigned v2) {
   522      /*
   523       * The upper bit of hash values is always set, so we have to operate on
   524       * 31-bit hashes here.
   525       */
   526      v1 ^= v2;
   527      v1 += HASH_ROL31(v2, 5);
